    public List<QualityRule> testGetAll() throws Throwable {
    LOGGER.info( "QualityRuleTest:testGetAll() - Retrieving Collection of QualityRules:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all QualityRule : " );
    List<QualityRule> collection  = null;

    try {
        // call the static get method on the QualityRuleService
        collection = service.getAllQualityRule();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            QualityRule currEntity  = null;
            Iterator<QualityRule> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getQualityRuleId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

